INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 14, 'theory', 'Quiz: a processor from blocks');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 0, 'Why do block ports have types?', '["To save memory", "To make blocks run faster", "So that incompatible buses can''t be connected — the interface is checked before running", "It is only for a pretty diagram"]', 2, 'A port type is a contract: Word2 and Addr2 have the same width but mean different things. Incompatible ports are joined through an adapter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 1, 'What does the fetch block do?', '["Holds the program counter, chooses the next address, and pulls the instruction from the ROM", "Performs arithmetic", "Decodes the operation code", "Supplies the clock signal"]', 0, 'Fetch is responsible for the PC, the next-address circuit, and the ROM. What the instruction is for is decided by the decoder.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 2, 'Which signal returns from the execute block to the decoder?', '["Clock", "Jump address", "Operation code", "The zero flag Z (the accumulator is zero)"]', 3, 'From Z the decoder decides whether to take the JNZ jump. The other signals go from the decoder to the blocks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 3, 'How many external inputs does the processor assembled in this chapter have?', '["None", "One: the clock", "Three: clock, reset, halt", "Four: one per block"]', 1, 'The program sits in the ROM inside the fetch block, and everything else is generated internally. The sequencer needs only the clock.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 14, 4, 'What happens at the end of the program LDI 2, ADD 1, JNZ 1, HLT?', '["ADD brings the accumulator back to zero (in two bits), JNZ doesn''t jump, and HLT stops the processor", "The processor jumps forever", "HLT triggers immediately", "An overflow error"]', 0, 'The accumulator goes through 2, 3, 0 (four doesn''t fit in two bits). Once it is zero, JNZ doesn''t jump, and we reach HLT.');
